/* =========================================================
 * MODULE 1 — KIỂM TRA TƯƠNG TÁC CHỐNG CHỈ ĐỊNH
 * ========================================================= */

/**
 * Chuẩn hóa tên thuốc để so khớp.
 */
function normalizeInteractionDrugName(value) {
  return String(value == null ? '' : value)
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}


/**
 * Kiểm tra một cặp thuốc có nằm trong danh mục
 * tương tác chống chỉ định hay không.
 *
 * @param {string} drugA
 * @param {string} drugB
 * @returns {Object|null}
 */
function checkContraindicatedInteraction(drugA, drugB) {
  const a = normalizeInteractionDrugName(drugA);
  const b = normalizeInteractionDrugName(drugB);

  if (!a || !b) {
    return null;
  }

  return (
    DRUG_INTERACTIONS_CI.find(function (row) {
      const d1 =
        normalizeInteractionDrugName(
          row.d1
        );

      const d2 =
        normalizeInteractionDrugName(
          row.d2
        );

      return (
        (d1 === a && d2 === b) ||
        (d1 === b && d2 === a)
      );
    }) || null
  );
}


/**
 * Kiểm tra nhiều thuốc cùng lúc.
 *
 * Trả về tất cả cặp chống chỉ định tìm được.
 */
function findAllContraindicatedInteractions(drugs) {
  if (!Array.isArray(drugs)) {
    return [];
  }

  const cleaned = drugs
    .map(function (drug) {
      return String(
        drug == null
          ? ''
          : drug
      ).trim();
    })
    .filter(Boolean);

  const results = [];

  for (
    let i = 0;
    i < cleaned.length;
    i += 1
  ) {
    for (
      let j = i + 1;
      j < cleaned.length;
      j += 1
    ) {
      const interaction =
        checkContraindicatedInteraction(
          cleaned[i],
          cleaned[j]
        );

      if (interaction) {
        results.push({
          first: cleaned[i],
          second: cleaned[j],

          d1: interaction.d1,
          d2: interaction.d2,

          mechanism:
            interaction.mechanism || '',

          consequence:
            interaction.consequence || '',

          management:
            interaction.management || '',

          severity:
            'contraindicated'
        });
      }
    }
  }

  return results;
}


/* =========================================================
 * API MODULE 1
 * ========================================================= */

const INTERACTIONS_CI_API = {
  data:
    DRUG_INTERACTIONS_CI,

  normalizeDrugName:
    normalizeInteractionDrugName,

  checkContraindicatedInteraction:
    checkContraindicatedInteraction,

  findAllContraindicatedInteractions:
    findAllContraindicatedInteractions
};


/* =========================================================
 * EXPORT CHO TRÌNH DUYỆT
 * ========================================================= */

if (typeof window !== 'undefined') {
  window.DRUG_INTERACTIONS_CI =
    DRUG_INTERACTIONS_CI;

  window.normalizeInteractionDrugName =
    normalizeInteractionDrugName;

  window.checkContraindicatedInteraction =
    checkContraindicatedInteraction;

  window.findAllContraindicatedInteractions =
    findAllContraindicatedInteractions;

  window.INTERACTIONS_CI_API =
    INTERACTIONS_CI_API;
}


/* =========================================================
 * EXPORT CHO NODE / TEST
 * ========================================================= */

if (
  typeof module !== 'undefined' &&
  module.exports
) {
  module.exports = {
    DRUG_INTERACTIONS_CI:
      DRUG_INTERACTIONS_CI,

    normalizeInteractionDrugName:
      normalizeInteractionDrugName,

    checkContraindicatedInteraction:
      checkContraindicatedInteraction,

    findAllContraindicatedInteractions:
      findAllContraindicatedInteractions,

    INTERACTIONS_CI_API:
      INTERACTIONS_CI_API
  };
}